 if(e.hasTop)list.push(['penthouse','Penthouse floor plan',H.floorPlanSVG(e,h,true)]);h.units.filter(u=>+u.size>0).forEach((u,i)=>list.push(['unit'+i,'Unit layout – '+u.name,H.unitSVG(u)]));
